import{_ as e,c as r,o as a,ag as d}from"./chunks/framework.CoPVQkzc.js";const m=JSON.parse('{"title":"Data Types and Formats","description":"Supported healthcare standards and data formats","frontmatter":{"title":"Data Types and Formats","description":"Supported healthcare standards and data formats"},"headers":[],"relativePath":"engine/data_types_and_formats.md","filePath":"engine/data_types_and_formats.md","lastUpdated":1788476353000}'),o={name:"engine/data_types_and_formats.md"};function n(s,t,i,l,p,c){return a(),r("div",null,t[0]||(t[0]=[d('<h1 id="data-types-and-formats" tabindex="-1">Data Types and Formats <a class="header-anchor" href="#data-types-and-formats" aria-label="Permalink to &quot;Data Types and Formats&quot;">​</a></h1><p>Data types control how OIE interprets incoming data and produces outgoing data. On the inbound side, the data type <strong>serializes</strong> raw content into an internal representation (typically XML) that filters and transformers can work with. On the outbound side, it <strong>deserializes</strong> the modified internal representation back into a concrete output format. This two-step process is what enables OIE to convert between entirely different message formats within a single channel.</p><h2 id="how-data-types-work" tabindex="-1">How data types work <a class="header-anchor" href="#how-data-types-work" aria-label="Permalink to &quot;How data types work&quot;">​</a></h2><p>The properties available for a given data type depend on two factors: whether it is being used as inbound or outbound, and whether it is attached to a source connector, a destination connector, or a destination&#39;s response. The property groups that may appear are:</p><h3 id="inbound-properties" tabindex="-1">Inbound properties <a class="header-anchor" href="#inbound-properties" aria-label="Permalink to &quot;Inbound properties&quot;">​</a></h3><ul><li><strong>Serialization Properties</strong>. Configure how raw data is converted into the internal format. Some data types (like DICOM and JSON) handle this automatically and have no serialization settings. The Raw data type skips serialization entirely.</li><li><strong>Batch Properties</strong>. Define how to divide a single inbound payload into multiple messages. Only relevant when Process Batch is turned on in the source settings, and not every data type supports batching.</li><li><strong>Response Generation Properties</strong>. Control how automatic responses (such as HL7 ACKs) are constructed. These only appear for source connectors when auto-generation is selected in the response settings.</li><li><strong>Response Validation Properties</strong>. Define how to evaluate responses returned by external systems. Only visible for destination connectors with response validation turned on.</li></ul><h3 id="outbound-properties" tabindex="-1">Outbound properties <a class="header-anchor" href="#outbound-properties" aria-label="Permalink to &quot;Outbound properties&quot;">​</a></h3><ul><li><strong>Deserialization Properties</strong>. Configure how data is converted from the internal format back into the target output format. Some data types (DICOM, EDI/X12, JSON) need no configuration here, and Raw performs no conversion at all.</li><li><strong>Template Serialization</strong>. When an outbound template is defined for a transformer, these settings control how that template gets parsed into the internal format.</li></ul><h2 id="supported-data-types" tabindex="-1">Supported data types <a class="header-anchor" href="#supported-data-types" aria-label="Permalink to &quot;Supported data types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Delimited Text</strong></td><td>Handles CSV, TSV, fixed-width, and other custom-delimited formats with configurable separators</td></tr><tr><td><strong>DICOM</strong></td><td>For medical imaging data. Automatically handles conversion between binary DICOM and an XML representation. No serialization settings to configure.</td></tr><tr><td><strong>EDI / X12</strong></td><td>Supports UN/EDIFACT, ASC X12, and similar formats built around segment, element, and subelement delimiters</td></tr><tr><td><strong>HL7 v2.x</strong></td><td>The standard pipe-delimited HL7 Version 2 format. Offers strict and non-strict parsing, auto-generated ACKs, response validation, and MSH-based batch splitting.</td></tr><tr><td><strong>HL7 v3.x</strong></td><td>XML-based HL7 Version 3. Since the wire format is already XML, no serialization/deserialization conversion is needed. Includes an option to remove namespace declarations.</td></tr><tr><td><strong>JSON</strong></td><td>JavaScript Object Notation. The <code>msg</code> and <code>tmp</code> variables become native JavaScript objects instead of E4X XML. No serialization configuration required.</td></tr><tr><td><strong>NCPDP</strong></td><td>Pharmacy data in the National Council for Prescription Drug Programs format. Uses configurable field, group, and segment delimiters.</td></tr><tr><td><strong>Raw</strong></td><td>A pass-through data type for arbitrary content. The <code>msg</code> and <code>tmp</code> variables are plain Java Strings. No conversion is performed in either direction.</td></tr><tr><td><strong>XML</strong></td><td>Generic XML. Like HL7 v3.x, the wire format matches the internal representation, so no conversion is needed. Has a namespace-stripping option.</td></tr></tbody></table><h2 id="internal-representation" tabindex="-1">Internal representation <a class="header-anchor" href="#internal-representation" aria-label="Permalink to &quot;Internal representation&quot;">​</a></h2><p>Different data types use different object types internally:</p><ul><li><strong>HL7 v2.x, HL7 v3.x, XML, EDI/X12, NCPDP, Delimited Text, DICOM</strong>. The <code>msg</code> and <code>tmp</code> variables are E4X XML objects. You access fields using bracket notation like <code>msg[&#39;MSH&#39;][&#39;MSH.9&#39;][&#39;MSH.9.1&#39;]</code>.</li><li><strong>JSON</strong>. The variables are standard JavaScript objects. Field access uses standard dot or bracket notation.</li><li><strong>Raw</strong>. The variables are Java Strings. You work with them using string operations.</li></ul><h2 id="setting-data-types" tabindex="-1">Setting data types <a class="header-anchor" href="#setting-data-types" aria-label="Permalink to &quot;Setting data types&quot;">​</a></h2><p>Each connector has separate inbound and outbound data type settings, accessible through the <strong>Set Data Types</strong> window on the channel&#39;s Summary tab.</p><p>To perform cross-format transformations, assign different inbound and outbound types. For example:</p><ul><li><strong>Source inbound</strong>: HL7 v2.x (received from a clinical system)</li><li><strong>Source outbound</strong>: XML (intermediate format)</li><li><strong>Destination inbound</strong>: XML</li><li><strong>Destination outbound</strong>: JSON (delivered to a REST API)</li></ul><p>The engine handles all format conversions automatically at each boundary.</p><h2 id="data-type-properties" tabindex="-1">Data type properties <a class="header-anchor" href="#data-type-properties" aria-label="Permalink to &quot;Data type properties&quot;">​</a></h2><h3 id="hl7-v2-x-properties" tabindex="-1">HL7 v2.x properties <a class="header-anchor" href="#hl7-v2-x-properties" aria-label="Permalink to &quot;HL7 v2.x properties&quot;">​</a></h3><p><strong>Serialization / Template Serialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Parse Field Repetitions</td><td>Enabled</td><td>Handle field repetitions (non-strict parser only)</td></tr><tr><td>Parse Subcomponents</td><td>Enabled</td><td>Handle subcomponents (non-strict parser only)</td></tr><tr><td>Use Strict Parser</td><td>Disabled</td><td>Use the HL7 specification-based parser instead of the simplified non-strict parser</td></tr><tr><td>Validate in Strict Parser</td><td>Disabled</td><td>Enforce HL7 specification rules during parsing (strict parser only)</td></tr><tr><td>Strip Namespaces</td><td>Disabled</td><td>Remove namespace declarations from the XML output (strict parser only)</td></tr><tr><td>Segment Delimiter</td><td><code>\\r</code></td><td>Character(s) expected between segments in the raw message</td></tr><tr><td>Convert Line Breaks</td><td>Enabled</td><td>Normalize all line break styles (CRLF, CR, LF) to the configured segment delimiter</td></tr></tbody></table><p><strong>Deserialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Use Strict Parser</td><td>Disabled</td><td>Use the HL7 specification-based parser</td></tr><tr><td>Validate in Strict Parser</td><td>Disabled</td><td>Enforce HL7 specification rules during parsing (strict parser only)</td></tr><tr><td>Segment Delimiter</td><td><code>\\r</code></td><td>Delimiter character(s) placed after each segment in the output</td></tr></tbody></table><p><strong>Response Generation:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Segment Delimiter</td><td><code>\\r</code></td><td>Delimiter character(s) used after each segment in the generated ACK</td></tr><tr><td>Successful ACK Code</td><td>AA</td><td>Code placed in the ACK when processing succeeds</td></tr><tr><td>Successful ACK Message</td><td><em>(empty)</em></td><td>Message text placed in the ACK when processing succeeds</td></tr><tr><td>Error ACK Code</td><td>AE</td><td>Code placed in the ACK when an error occurs</td></tr><tr><td>Error ACK Message</td><td>An Error Occurred Processing Message.</td><td>Message text placed in the ACK when an error occurs</td></tr><tr><td>Rejected ACK Code</td><td>AR</td><td>Code placed in the ACK when the message is filtered</td></tr><tr><td>Rejected ACK Message</td><td>Message Rejected.</td><td>Message text placed in the ACK when the message is filtered</td></tr><tr><td>MSH-15 ACK Accept</td><td>Disabled</td><td>Check MSH-15 to control whether/when to acknowledge</td></tr><tr><td>Date Format</td><td>yyyyMMddHHmmss.SSS</td><td>Format string for timestamps in generated ACKs</td></tr></tbody></table><p><strong>Response Validation:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Successful ACK Codes</td><td>AA,CA</td><td>Codes in a response that indicate acceptance (message marked SENT)</td></tr><tr><td>Error ACK Codes</td><td>AE,CE</td><td>Codes that indicate an error on the receiving end (message marked ERROR)</td></tr><tr><td>Rejected ACK Codes</td><td>AR,CR</td><td>Codes that indicate rejection (message marked ERROR)</td></tr><tr><td>Validate Message Control Id</td><td>Enabled</td><td>Confirm that MSA-2 in the response matches the original message control ID</td></tr><tr><td>Original Message Control Id</td><td>Destination Encoded</td><td>Source of the original message control ID for validation. Choose Destination Encoded (from MSH-10 of destination encoded content) or Map Variable.</td></tr><tr><td>Original Id Map Variable</td><td><em>(empty)</em></td><td>Variable name in the connector map or channel map to read the original message control ID from (only used when Original Message Control Id is set to Map Variable)</td></tr></tbody></table><h3 id="delimited-text-properties" tabindex="-1">Delimited text properties <a class="header-anchor" href="#delimited-text-properties" aria-label="Permalink to &quot;Delimited text properties&quot;">​</a></h3><p><strong>Serialization / Template Serialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Column Delimiter</td><td><code>,</code></td><td>Separator between columns</td></tr><tr><td>Record Delimiter</td><td><code>\\n</code></td><td>Separator between records</td></tr><tr><td>Column Widths</td><td></td><td>Comma-separated fixed widths (leave blank for delimiter-based parsing)</td></tr><tr><td>Quote Token</td><td><code>&quot;</code></td><td>Character(s) used to wrap column values that contain special characters</td></tr><tr><td>Double Quote Escaping</td><td>Enabled</td><td>Treat two consecutive quote tokens as an embedded quote. Disable to use the Escape Token instead.</td></tr><tr><td>Escape Token</td><td><code>\\</code></td><td>Character(s) used to escape quote tokens (only takes effect when Double Quote Escaping is disabled)</td></tr><tr><td>Column Names</td><td></td><td>Comma-separated custom names (defaults to column1, column2, etc.)</td></tr><tr><td>Numbered Rows</td><td>Disabled</td><td>Number each row in the XML representation</td></tr><tr><td>Ignore Carriage Returns</td><td>Enabled</td><td>Skip over carriage return (<code>\\r</code>) characters without processing them</td></tr></tbody></table><p><strong>Deserialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Column Delimiter</td><td><code>,</code></td><td>Separator between columns</td></tr><tr><td>Record Delimiter</td><td><code>\\n</code></td><td>Separator between records</td></tr><tr><td>Column Widths</td><td></td><td>Comma-separated fixed widths (leave blank for delimiter-based parsing)</td></tr><tr><td>Quote Token</td><td><code>&quot;</code></td><td>Character(s) used to wrap column values that contain special characters</td></tr><tr><td>Double Quote Escaping</td><td>Enabled</td><td>Treat two consecutive quote tokens as an embedded quote. Disable to use the Escape Token instead.</td></tr><tr><td>Escape Token</td><td><code>\\</code></td><td>Character(s) used to escape quote tokens (only takes effect when Double Quote Escaping is disabled)</td></tr></tbody></table><h3 id="edi-x12-properties" tabindex="-1">EDI / X12 properties <a class="header-anchor" href="#edi-x12-properties" aria-label="Permalink to &quot;EDI / X12 properties&quot;">​</a></h3><p><strong>Serialization / Template Serialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Segment Delimiter</td><td><code>~</code></td><td>Separator between segments</td></tr><tr><td>Element Delimiter</td><td><code>*</code></td><td>Separator between elements</td></tr><tr><td>Subelement Delimiter</td><td><code>:</code></td><td>Separator between subelements</td></tr><tr><td>Infer X12 Delimiters</td><td>Enabled</td><td>For X12 messages, detect delimiters from the message itself rather than using the configured values</td></tr></tbody></table><h3 id="ncpdp-properties" tabindex="-1">NCPDP properties <a class="header-anchor" href="#ncpdp-properties" aria-label="Permalink to &quot;NCPDP properties&quot;">​</a></h3><p><strong>Serialization / Template Serialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Field Delimiter</td><td>0x1C</td><td>Separator between fields</td></tr><tr><td>Group Delimiter</td><td>0x1D</td><td>Separator between groups</td></tr><tr><td>Segment Delimiter</td><td>0x1E</td><td>Separator between segments</td></tr></tbody></table><p><strong>Deserialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Field Delimiter</td><td>0x1C</td><td>Separator between fields</td></tr><tr><td>Group Delimiter</td><td>0x1D</td><td>Separator between groups</td></tr><tr><td>Segment Delimiter</td><td>0x1E</td><td>Separator between segments</td></tr><tr><td>Use Strict Validation</td><td>Disabled</td><td>Check the message against the NCPDP schema</td></tr></tbody></table><h3 id="xml-properties" tabindex="-1">XML properties <a class="header-anchor" href="#xml-properties" aria-label="Permalink to &quot;XML properties&quot;">​</a></h3><p><strong>Serialization / Template Serialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Strip Namespaces</td><td>Disabled</td><td>Remove namespace declarations from the XML</td></tr></tbody></table><h3 id="hl7-v3-x-properties" tabindex="-1">HL7 v3.x properties <a class="header-anchor" href="#hl7-v3-x-properties" aria-label="Permalink to &quot;HL7 v3.x properties&quot;">​</a></h3><p><strong>Serialization / Template Serialization:</strong></p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Strip Namespaces</td><td>Disabled</td><td>Remove namespace declarations from the XML</td></tr></tbody></table><h2 id="batch-processing-by-data-type" tabindex="-1">Batch processing by data type <a class="header-anchor" href="#batch-processing-by-data-type" aria-label="Permalink to &quot;Batch processing by data type&quot;">​</a></h2><p>Each data type offers different methods for splitting inbound data when Process Batch is enabled:</p><table tabindex="0"><thead><tr><th>Data Type</th><th>Batch Split Options</th></tr></thead><tbody><tr><td><strong>Delimited Text</strong></td><td>Record, Delimiter, Grouping Column, JavaScript</td></tr><tr><td><strong>EDI / X12</strong></td><td>JavaScript only</td></tr><tr><td><strong>HL7 v2.x</strong></td><td>MSH Segment, JavaScript</td></tr><tr><td><strong>HL7 v3.x</strong></td><td>JavaScript only</td></tr><tr><td><strong>JSON</strong></td><td>JavaScript only</td></tr><tr><td><strong>NCPDP</strong></td><td>JavaScript only</td></tr><tr><td><strong>Raw</strong></td><td>JavaScript only</td></tr><tr><td><strong>XML</strong></td><td>Element Name, Level, XPath Query, JavaScript</td></tr></tbody></table><p>Every data type supports a <strong>JavaScript batch script</strong> option. Within the script, you have access to a <code>reader</code> variable, a Java BufferedReader connected to the inbound data stream. Your script reads from it and returns a String for each message. Return null or an empty string to signal that no more messages remain.</p>',51)]))}const u=e(o,[["render",n]]);export{m as __pageData,u as default};
